(() => {
 'use strict';
 const app=document.getElementById('app');
 let activeCategory='すべて', selected=null, revealed=false, currentCareer=null, step=0, answers=[];
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function focusHeading(){const h=app.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}window.scrollTo({top:0,behavior:'instant'});}
 function card(c){return `<a class="career" href="#career/${c.id}" style="--card-bg:${c.color};--card-ink:${c.ink}"><div class="career-art">${c.image?`<img src="${c.image}" alt="${esc(c.imageAlt)}" loading="lazy">`:`<span class="word-art" aria-hidden="true">${c.word}</span>`}<span class="art-label">${c.category}</span></div><div class="card-body"><h3>${c.name}</h3><p>${c.description}</p><div class="card-bottom"><span>約3分 · 3つのシーン</span><span class="card-arrow" aria-hidden="true">↗</span></div></div></a>`;}
 function home(){currentCareer=null;document.title='ミライシーン | 仕事のひと場面を体験しよう';app.innerHTML=`<div class="home"><section class="intro"><span class="eyebrow">仕事のひと場面を、あなたの選択で。</span><h1>ちょっと体験。<br>ぐっと近づく、<span>未来の自分。</span></h1><p>もし、自分がこの仕事をしていたら？<br>約3分の小さな体験から、気になる仕事を見つけよう。</p><div class="intro-stamp" aria-hidden="true"><span>知らなかった「好き」に</span><strong>出会う。</strong><span>3 MINUTE EXPERIENCE</span></div></section><section aria-labelledby="catalog-title"><div class="catalog-title"><h2 id="catalog-title">どの仕事を体験してみる？</h2><span>6つの仕事から選ぼう</span></div><div class="filters" role="group" aria-label="分野で絞り込む">${['すべて',...new Set(CAREERS.map(c=>c.category))].map(c=>`<button class="filter ${c===activeCategory?'active':''}" data-category="${c}" aria-pressed="${c===activeCategory}">${c}</button>`).join('')}</div><div class="grid" id="career-grid">${CAREERS.filter(c=>activeCategory==='すべて'||c.category===activeCategory).map(card).join('')}</div></section><section class="about-note"><div><h2>「向いている」より、「気になる」を。</h2><p>正解を当てるテストではありません。選んだ理由を振り返りながら、その仕事で大切にされる考え方に触れてみてください。</p></div><a class="text-link" href="#about">ミライシーンについて ↗</a></section></div>`;app.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.category;home();app.querySelector(`[data-category="${activeCategory}"]`).focus({preventScroll:true});});}
 function showScene(){const c=currentCareer,s=c.scenes[step];document.title=`${c.name}の仕事体験 | ミライシーン`;app.innerHTML=`<div class="experience"><a class="back" href="#">← 仕事一覧に戻る</a><div class="experience-top"><span>${c.category} / ${c.name}</span><span>SCENE ${String(step+1).padStart(2,'0')} / 03</span></div><div class="progress" aria-label="全3シーン中${step+1}シーン目">${c.scenes.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><article class="scene-card">${c.brief&&step===0?`<div class="brief"><strong>今回のミッション</strong><p>${c.mission}</p><dl><dt>役割</dt><dd>${c.brief.role}</dd><dt>相手</dt><dd>${c.brief.audience}</dd><dt>目的</dt><dd>${c.brief.goal}</dd><dt>条件</dt><dd>${c.brief.constraint}</dd></dl></div>`:''}<span class="scene-kicker">あなたなら、どうする？</span><h1>${s.title}</h1><p>${s.situation}</p>${s.image?`<img class="scene-image" src="${s.image}" alt="${esc(c.imageAlt)}">`:''}${s.comparison?'<div class="comparison"><figure><a href="assets/poster-a.png" target="_blank" rel="noopener" aria-label="A案を別タブで拡大"><img src="assets/poster-a.png" alt="A案。青い背景に大きな見出しと、イベントの日時を配置したポスター"></a><figcaption>A案 · 情報をはっきり伝える</figcaption></figure><figure><a href="assets/poster-b.png" target="_blank" rel="noopener" aria-label="B案を別タブで拡大"><img src="assets/poster-b.png" alt="B案。オレンジとピンクの表現を主役に、見出しを小さく配置したポスター"></a><figcaption>B案 · 雰囲気で興味を引く</figcaption></figure></div><p class="fine-print">画像を押すと、別タブで大きく見られます。</p>':''}<h2 class="question" id="question">${s.question}</h2><div class="options" role="group" aria-labelledby="question">${s.options.map((o,i)=>`<button class="option ${selected===i?'selected':''}" data-option="${i}" aria-pressed="${selected===i}" ${revealed?'disabled':''}><span class="option-letter">${'ABC'[i]}</span><span>${o[0]}</span></button>`).join('')}</div>${revealed?`<section class="feedback" tabindex="-1"><span class="selected-caption">あなたが選んだのは ${'ABC'[selected]}</span><h2>この選択にある、仕事の視点。</h2><p>${s.options[selected][1]}</p>${s.effects?`<div class="effects"><div><strong>この方法のよさ</strong><p>${s.effects[selected][0]}</p></div><div><strong>気をつけたいこと</strong><p>${s.effects[selected][1]}</p></div></div>`:''}<details class="other-choices"><summary>ほかの選択の視点も見る</summary>${s.options.map((o,i)=>i===selected?'':`<section><h3>${'ABC'[i]} · ${o[0]}</h3><p>${o[1]}</p></section>`).join('')}</details><div class="perspective"><strong>この仕事で大切にしたいこと</strong><p>${s.perspective}</p></div><p class="fine-print">状況や相手によって、必要な対応は変わります。</p><div class="actions"><button class="primary" id="next">${step===2?'体験を振り返る':'次のシーンへ'} <span>→</span></button></div></section>`:`<div class="actions"><button class="primary" id="explain" ${selected===null?'disabled':''}>この選択の視点を見る <span>→</span></button></div>`}</article></div>`;app.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.option);app.querySelectorAll('[data-option]').forEach(v=>{v.classList.toggle('selected',v===b);v.setAttribute('aria-pressed',String(v===b));});document.getElementById('explain').disabled=false;});const explain=document.getElementById('explain');if(explain)explain.onclick=()=>{if(selected===null)return;answers[step]=selected;revealed=true;showScene();const f=app.querySelector('.feedback');f.focus({preventScroll:true});f.scrollIntoView({behavior:'smooth',block:'start'});};const next=document.getElementById('next');if(next)next.onclick=()=>{if(step===2){finish();}else{step++;selected=null;revealed=false;showScene();}focusHeading();};}
 function finish(){const c=currentCareer;document.title=`${c.name}の体験を振り返る | ミライシーン`;app.innerHTML=`<div class="experience"><a class="back" href="#">← 仕事一覧に戻る</a><article class="scene-card"><div class="finish-intro"><div class="finish-icon" aria-hidden="true">✦</div><span class="scene-kicker">3つのシーンを体験しました</span><h1>${c.name}の<br>仕事、どう感じた？</h1><p>少しでも「気になる」があったら、<br>それが次の一歩のきっかけです。</p></div><h2 class="question">今回出会った、3つの視点</h2><ul class="insights">${c.scenes.map((s,i)=>`<li><b>0${i+1}</b><div><strong>${s.insight}</strong>${answers[i]!==undefined?`<p class="answer-record">あなたの選択：${s.options[answers[i]][0]}</p>`:''}<p>${s.perspective}</p></div></li>`).join('')}</ul><h2 class="question">もっと知りたいなら、この学びから。</h2><div class="study-links">${c.studies.map(s=>`<span>${s}</span>`).join('')}</div><p class="fine-print">学びの名称や学べる内容は学校によって異なります。資格が必要な職業は、取得までの課程も学校の公式情報で確認しましょう。</p><a class="text-link" href="https://shinronavi.com/" target="_blank" rel="noopener">進路ナビで学校を探す ↗</a><p class="fine-print">外部サイトが開きます。職業や学問の名前を手がかりに探してみてください。</p><h2 class="question">別の仕事にも、出会ってみよう。</h2><div class="next-careers">${CAREERS.filter(v=>v.id!==c.id).slice(0,2).map(v=>`<a href="#career/${v.id}">${v.name} ↗</a>`).join('')}</div><div class="actions"><a class="primary" href="#">仕事一覧に戻る →</a></div></article></div>`;}
 function about(){document.title='ミライシーンについて | ミライシーン';app.innerHTML='<div class="experience about-page"><a class="back" href="#">← 仕事一覧に戻る</a><article class="scene-card"><span class="scene-kicker">ABOUT MIRAI SCENE</span><h1>仕事の名前の、その先へ。</h1><p>知っている職業でも、そこで働く人が何を考えているのかは、なかなか見えないもの。ミライシーンは、仕事のひと場面で「自分ならどうする？」を選ぶ、約3分の仕事体験です。</p><h2>あなたの適性を決めるものではありません。</h2><p>選択に点数や合否はありません。選択の解説を通して、仕事で大切にされる考え方の一部を紹介します。仕事の全体像や、専門的な判断をそのまま再現するものではありません。</p><h2>体験から、学びへ。</h2><p>気になる仕事が見つかったら、関連する学問や学校について調べたり、オープンキャンパスで話を聞いたりしてみてください。</p><h2>この試作版について</h2><p>掲載している場面・人物・デザイン例は架空の設定です。コンテンツは制作時にAIを活用した編集用の下書きで、専門家による監修は未実施です。正式公開に向けて内容を確認・改善していきます。進路ナビの公式サービスとして提供されているものではありません。</p><div class="actions"><a href="#" class="primary">仕事を体験してみる →</a></div></article></div>';}
 function route(){const h=location.hash.slice(1);if(h==='about'){about();}else if(h.startsWith('career/')){const c=CAREERS.find(v=>v.id===h.split('/')[1]);if(c){currentCareer=c;step=0;answers=[];selected=null;revealed=false;showScene();}else{home();}}else{home();}focusHeading();}
 window.addEventListener('hashchange',route);route();
 // Small explicit tools for browser agents; same actions and content as the visible interface.
 const context=document.modelContext || navigator.modelContext;
 if(context?.registerTool){
  const lifecycle=new AbortController();
  const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
  register({name:'list_careers',description:'List available career experiences.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>CAREERS.map(({id,name,category})=>({id,name,category}))});
  register({name:'open_career',description:'Start a career experience and reset its current answers.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||typeof input.id!=='string'||!CAREERS.some(c=>c.id===input.id))return {error:'Unknown career ID'};history.replaceState(null,'','#career/'+input.id);route();return {opened:input.id};}});
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 }
})();
